const long frequency=1000000000;int checks=0;void Check(bool b,string name){if(!b)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}int Count(int requested,int source,bool jitter=false){var clock=new FrameClock(requested,frequency);int count=0;for(int i=0;i<source*6;i++){long t=i*frequency/source+(jitter?(i%2==0?-300000:300000):0);if(clock.Accept(t))count++;}return count;}
Check(Count(60,60)==360,"60Hz source stays at 60FPS instead of integer-ms halving");Check(Count(30,60)==180,"30FPS target drops only alternate 60Hz frames");Check(Count(10,60)==60,"10FPS target correctly samples 60Hz source");Check(Count(60,60,true)>=358,"sub-millisecond capture jitter does not halve 60FPS");Check(Count(60,30)==180,"30Hz source is not reported as synthetic 60FPS");var stall=new FrameClock(60,frequency);stall.Accept(0);Check(stall.Accept(frequency*10),"resume after stall accepts the latest frame");Check(!stall.Accept(frequency*10),"resume does not emit a catch-up burst");Console.WriteLine(checks+" frame scheduling checks passed");